<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Service; use App\Models\ServiceCategory; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Support\Facades\Storage; use Illuminate\View\View; use Illuminate\Http\RedirectResponse;
class ServiceAdminController extends Controller { public function index():View{return view('admin.services.index',['services'=>Service::with('serviceCategory')->orderBy('sort_order')->get(),'categories'=>ServiceCategory::orderBy('sort_order')->orderBy('name')->get()]);} public function store(Request $r):RedirectResponse{$v=$r->validate(['name'=>'required|string|max:150','category'=>'nullable|string|max:100','service_category_id'=>'nullable|exists:service_categories,id','description'=>'nullable|string|max:3000','image'=>'nullable|image|max:5120','name_de'=>'nullable|string|max:200','name_fr'=>'nullable|string|max:200','name_en'=>'nullable|string|max:200','description_de'=>'nullable|string|max:3000','description_fr'=>'nullable|string|max:3000','description_en'=>'nullable|string|max:3000','price'=>'required|numeric|min:0','price_from'=>'nullable|boolean','duration_minutes'=>'required|integer|min:15|max:600','at_salon'=>'nullable|boolean','at_home'=>'nullable|boolean','travel_fee'=>'nullable|numeric|min:0','conditions'=>'nullable|string|max:3000','is_active'=>'nullable|boolean','sort_order'=>'nullable|integer|min:0']);if ($r->hasFile('image')) $v['image_path'] = $r->file('image')->store('services','public'); unset($v['image']); $category = !empty($v['service_category_id']) ? ServiceCategory::find($v['service_category_id']) : null; $v['category'] = $category?->name ?? ($v['category'] ?? 'Coiffure'); $v['slug']=Str::slug($v['name']).'-'.Str::lower(Str::random(5));foreach(['price_from','at_salon','at_home','is_active'] as $k)$v[$k]=(bool)($v[$k]??false);$v['travel_fee']=$v['travel_fee']??0;$v['sort_order']=$v['sort_order']??0;Service::create($v);return back()->with('success','Prestation créée.');} public function update(Request $r,Service $service):RedirectResponse{$v=$r->validate(['name'=>'required|string|max:150','category'=>'nullable|string|max:100','service_category_id'=>'nullable|exists:service_categories,id','description'=>'nullable|string|max:3000','image'=>'nullable|image|max:5120','name_de'=>'nullable|string|max:200','name_fr'=>'nullable|string|max:200','name_en'=>'nullable|string|max:200','description_de'=>'nullable|string|max:3000','description_fr'=>'nullable|string|max:3000','description_en'=>'nullable|string|max:3000','price'=>'required|numeric|min:0','price_from'=>'nullable|boolean','duration_minutes'=>'required|integer|min:15|max:600','at_salon'=>'nullable|boolean','at_home'=>'nullable|boolean','travel_fee'=>'nullable|numeric|min:0','conditions'=>'nullable|string|max:3000','is_active'=>'nullable|boolean','sort_order'=>'nullable|integer|min:0']);$category = !empty($v['service_category_id']) ? ServiceCategory::find($v['service_category_id']) : null; $v['category'] = $category?->name ?? ($v['category'] ?? $service->category);foreach(['price_from','at_salon','at_home','is_active'] as $k)$v[$k]=(bool)($v[$k]??false);if($r->hasFile('image')){if($service->image_path)Storage::disk('public')->delete($service->image_path);$v['image_path']=$r->file('image')->store('services','public');}unset($v['image']);$service->update($v);return back()->with('success','Prestation mise à jour.');} public function destroy(Service $service):RedirectResponse{if($service->bookings()->exists()){$service->update(['is_active'=>false]);return back()->with('success','Prestation désactivée car elle possède un historique de rendez-vous.');}if($service->image_path)Storage::disk('public')->delete($service->image_path);$service->delete();return back()->with('success','Prestation supprimée.');} }
